#include <stdio.h>
#include <string.h>

static void print_str_int_map(const char **keys, const int *vals, int n) {
    printf("map[");
    for (int i = 0; i < n; i++) {
        if (i) putchar(' ');
        printf("%s:%d", keys[i], vals[i]);
    }
    printf("]");
}
static int map_get_str_int(const char **keys, const int *vals, int n,
                           const char *key, int *found) {
    for (int i = 0; i < n; i++)
        if (strcmp(keys[i], key) == 0) { *found = 1; return vals[i]; }
    *found = 0;
    return 0;
}

int main(void) {
    const char *keys[] = {"Alice", "Bob"};
    int vals[] = {25, 30};
    print_str_int_map(keys, vals, 2);
    putchar('\n');
    return 0;
}

